{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "In healthy subjects, 17-BMP absolute oral bioavailability was 41% (90% CI 31-54%) after oral versus IV administration, exceeding the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "In healthy young women, NOMAC absolute oral bioavailability was 63.4% (95% CI 51.7-77.8%) after oral versus IV administration, exceeding the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "In healthy male volunteers, danazol absolute oral bioavailability was 11 ± 5.2% after a standard 100 mg oral dose in the fasted state, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high because the transferred human absolute/systemic oral bioavailability evidence is predominantly above 20%, with multiple values from 41% to ~100%; the only clearly sub-20% record is fasted standard danazol, which is outweighed by the consistent high-F evidence.",
  "evidence_gaps": [
    "Danazol oral bioavailability is strongly formulation- and food-dependent; the low fasted standard-capsule value conflicts with higher fed/emulsion values, so the condition match for that contradictory record is uncertain.",
    "Molecule 3 (ABA) evidence is qualitative and derived from an apricot food matrix rather than a direct absolute F measurement, making it uninformative for threshold classification.",
    "Some records report systemic availability rather than absolute oral bioavailability, but they align with the high-F direction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

